<?php require_once 'bootstrap.php';$u=require_login();$sic=$_GET['form']??$_POST['form']??'';$st=db()->prepare("SELECT * FROM form_templates WHERE sic_id=? AND status='ACTIVE'");$st->execute([$sic]);$f=$st->fetch();if(!$f){http_response_code(404);exit('Modulo non trovato');}$schema=json_decode($f['schema_json'],true);$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$payload=[];foreach($schema['fields']??[] as $field){$payload[$field['name']]=trim((string)($_POST[$field['name']]??''));if(!empty($field['required'])&&$payload[$field['name']]==='')throw new RuntimeException('Campo obbligatorio: '.$field['label']);}$ss=sic_id();db()->prepare('INSERT INTO form_submissions(sic_id,form_sic_id,user_sic_id,scope_sic_id,payload_json) VALUES(?,?,?,?,?)')->execute([$ss,$sic,$u['sic_id'],null,json_encode($payload,JSON_UNESCAPED_UNICODE)]);audit($u['sic_id'],'FORM_SUBMIT',$ss,['form'=>$f['code']]);$done=true;}$pageTitle=$f['title'];require '_header.php';?>
<section class="card"><span class="eyebrow">Form Factory</span><h1><?=h($f['title'])?></h1><?php if($done):?><div class="success">✓ Modulo registrato con SIC-ID.</div><?php endif;?><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="form" value="<?=h($sic)?>"><?php foreach($schema['fields']??[] as $x):?><label><?=h($x['label'])?><?php if($x['type']==='textarea'):?><textarea name="<?=h($x['name'])?>" <?=!empty($x['required'])?'required':''?>></textarea><?php elseif($x['type']==='select'):?><select name="<?=h($x['name'])?>" <?=!empty($x['required'])?'required':''?>><option value="">Seleziona</option><?php foreach($x['options']??[] as $o):?><option><?=h($o)?></option><?php endforeach;?></select><?php else:?><input type="<?=h($x['type'])?>" name="<?=h($x['name'])?>" <?=!empty($x['required'])?'required':''?>><?php endif;?></label><?php endforeach;?><button class="btn primary">Registra</button></form></section><?php require '_footer.php';?>